import java.nio.file.*;import java.util.*;import java.io.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import org.objectweb.asm.util.*;
public class OpeningDelta {
 static ClassNode read(byte[] b,int flags){var c=new ClassNode();new ClassReader(b).accept(c,flags);return c;}
 static String key(MethodNode m){return m.name+m.desc;}
 static String norm(MethodNode original){var shell=new ClassNode();shell.version=Opcodes.V21;shell.access=Opcodes.ACC_PUBLIC;shell.name="Fingerprint";shell.superName="java/lang/Object";shell.methods.add(original);var w=new ClassWriter(0);shell.accept(w);var copy=read(w.toByteArray(),ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES).methods.getFirst();copy.maxStack=0;copy.maxLocals=0;var p=new Textifier();copy.accept(new TraceMethodVisitor(p));var out=new StringWriter();p.print(new PrintWriter(out));return out.toString();}
 static boolean eq(MethodNode a,MethodNode b){return a!=null&&b!=null&&norm(a).equals(norm(b));}
 public static void main(String[] a)throws Exception{
 var live=read(Files.readAllBytes(Path.of(a[0])),0);var newer=read(Files.readAllBytes(Path.of(a[1])),0);var old=read(Files.readAllBytes(Path.of(a[2])),0);var changed=new HashSet<String>();var already=new HashSet<String>();var conflicts=new ArrayList<String>();
 var handled=OpeningSpecial.apply(live,newer,old,Path.of("C:/Chacademi/artifacts/opening-prep-safe-integration-20261025-task3/bounded-packaging/helper-classes"),changed);
 for(var m:newer.methods){if(handled.contains(key(m)))continue;var was=old.methods.stream().filter(x->key(x).equals(key(m))).findFirst().orElse(null);if(eq(was,m))continue;var current=live.methods.stream().filter(x->key(x).equals(key(m))).findFirst().orElse(null);if(eq(current,m)){already.add(key(m));continue;}if(was==null&&current!=null){conflicts.add("NEW_METHOD_COLLISION "+key(m));continue;}if(was!=null&&current!=null&&!eq(was,current)){conflicts.add("DEPLOYED_METHOD_DIVERGED "+key(m));continue;}if(current!=null)live.methods.remove(current);live.methods.add(m);changed.add(key(m));}
 for(var f:newer.fields){var was=old.fields.stream().filter(x->x.name.equals(f.name)).findFirst().orElse(null);var current=live.fields.stream().filter(x->x.name.equals(f.name)).findFirst().orElse(null);if(was==null){if(current==null)live.fields.add(f);else if(!current.desc.equals(f.desc)||current.access!=f.access||!Objects.equals(current.value,f.value))conflicts.add("NEW_FIELD_COLLISION "+f.name);}else if(!was.desc.equals(f.desc))conflicts.add("SOURCE_FIELD_DESCRIPTOR_CHANGED "+f.name);else if(was.access!=f.access||!Objects.equals(was.value,f.value)){if(current==null||!current.desc.equals(was.desc)||current.access!=was.access||!Objects.equals(current.value,was.value))conflicts.add("DEPLOYED_FIELD_DIVERGED "+f.name);else{current.access=f.access;current.value=f.value;}}}
 if(!conflicts.isEmpty()){for(String s:conflicts)System.out.println("CONFLICT "+live.name+" "+s);System.exit(2);}
 var originalMethods=new HashSet<String>();for(var m:read(Files.readAllBytes(Path.of(a[0])),0).methods)originalMethods.add(key(m));boolean grew=true;while(grew){grew=false;for(var m:new ArrayList<MethodNode>(live.methods)){if(!changed.contains(key(m))&&originalMethods.contains(key(m)))continue;var refs=new ArrayList<String>();for(var i:m.instructions.toArray()){if(i instanceof MethodInsnNode call&&call.owner.equals(live.name))refs.add(call.name+call.desc);if(i instanceof InvokeDynamicInsnNode dy)for(var x:dy.bsmArgs)if(x instanceof Handle h&&h.getOwner().equals(live.name)&&h.getTag()>=Opcodes.H_INVOKEVIRTUAL)refs.add(h.getName()+h.getDesc());}for(var ref:refs){if(live.methods.stream().anyMatch(x->key(x).equals(ref)))continue;var needed=newer.methods.stream().filter(x->key(x).equals(ref)).findFirst().orElse(null);if(needed!=null){live.methods.add(OpeningSpecial.copy(needed));changed.add(ref);grew=true;System.out.println("DEPENDENCY_ADDED "+live.name+"."+ref+" required by "+key(m));}}}}
 if(newer.permittedSubclasses!=null){if(live.permittedSubclasses==null)live.permittedSubclasses=new ArrayList<>();for(String member:newer.permittedSubclasses)if(!live.permittedSubclasses.contains(member)){live.permittedSubclasses.add(member);System.out.println("PERMITTED_SUBCLASS_ADDED "+live.name+" -> "+member);}}
 if(newer.nestMembers!=null){if(live.nestMembers==null)live.nestMembers=new ArrayList<>();for(String x:newer.nestMembers)if(!live.nestMembers.contains(x))live.nestMembers.add(x);}for(var ic:newer.innerClasses)if(live.innerClasses.stream().noneMatch(x->x.name.equals(ic.name)))live.innerClasses.add(ic);
 var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);live.accept(w);var out=w.toByteArray();var original=read(Files.readAllBytes(Path.of(a[0])),0);var actual=read(out,0);for(var m:original.methods){if(changed.contains(key(m)))continue;var now=actual.methods.stream().filter(x->key(x).equals(key(m))).findFirst().orElseThrow();if(!eq(m,now))throw new IllegalStateException("UNRELATED_METHOD_CHANGED "+live.name+" "+key(m));}for(var m:actual.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(actual.name,m);Files.write(Path.of(a[3]),out);System.out.println("PASS "+live.name+" changed="+changed+" already="+already+" preserved="+(original.methods.size()-changed.size()));
 }
}
